#ifndef TF_TRAFFIC_PAGES_H
#define TF_TRAFFIC_PAGES_H
static int traffic_draft_enabled=0;
static int traffic_integer(const char*s,long long min,long long max,long long*out){if(!*s)return 0;for(const char*p=s;*p;p++)if(!isdigit((unsigned char)*p))return 0;errno=0;char*end;long long value=strtoll(s,&end,10);if(errno||*end||value<min||value>max)return 0;*out=value;return 1;}
static void traffic_bytes(const tf_json*d,int t,const char*key,const char*label){long long value;char text[96];if(tf_int(d,tf_key(d,t,key),&value)&&value>=0)snprintf(text,sizeof text,"%.3f GiB",(double)value/1073741824.0);else strcpy(text,"—");modem_row(label,text);}
static void traffic_render(void){advanced_shell("主卡流量管理");tf_json d;if(!fresh_state(&d)){ah("<div class='hint'>流量数据不可用</div>");goto end;}int t=tf_key(&d,0,"traffic"),limit=tf_key(&d,t,"limit"),clear=tf_key(&d,t,"clear_day");ah("<div class='card'>");traffic_bytes(&d,t,"day_rx_bytes","今日下行");traffic_bytes(&d,t,"day_tx_bytes","今日上行");traffic_bytes(&d,t,"month_rx_bytes","本月下行");traffic_bytes(&d,t,"month_tx_bytes","本月上行");ah("</div><a class='button secondary' href='act:traffic-edit:0' style='margin-bottom:8px'>校正本月累计 / 清零</a>");long long type,cap,ratio,day;if(tf_int(&d,tf_key(&d,limit,"type"),&type)&&tf_int(&d,tf_key(&d,limit,"value"),&cap)&&tf_int(&d,tf_key(&d,limit,"ratio"),&ratio)){ah("<div class='card'><b>现有流量限额</b>");char v[96];snprintf(v,sizeof v,"%lld 字节",cap);modem_row("容量",v);snprintf(v,sizeof v,"%lld%%",ratio);modem_row("提醒比例",v);modem_row("状态",tf_bool(&d,tf_key(&d,limit,"enable"))==1?"开启":"关闭或未知");ah("<p class='note'>套餐类型意义尚未核实，限额配置保持只读。</p>");ah("</div>");}if(tf_int(&d,tf_key(&d,clear,"clearday"),&day)&&day>=1&&day<=31&&tf_bool(&d,tf_key(&d,clear,"enable"))>=0)ah("<a class='button secondary' href='act:traffic-edit:2'>每月清零日：%lld · 点击修改</a>",day);tf_free(&d);end:ah("<p class='note'>本页只作用于 5G 主卡。数值来自原厂计数，不代表运营商账单；不会推断未核实的限额类型。</p></div></body></html>");}
static void traffic_form_render(void){advanced_shell(traffic_op==0?"校正本月流量":traffic_op==1?"编辑现有流量限额":"每月清零设置");for(int i=0;i<(traffic_op==1?2:1);i++){char value[2048];esc(value,sizeof value,form_values[i]);ah("<a class='sms' href='act:edit:%d'><p class='note'>%s</p><b style='word-break:break-all'>%s</b></a>",i,form_label(i),value);}if(traffic_op)ah("<a class='button secondary' href='act:traffic-toggle' style='margin:8px 0'>规则：%s · 点击%s</a>",traffic_draft_enabled?"开启":"关闭",traffic_draft_enabled?"关闭":"开启");ah("<p class='note'>%s</p><a class='button' href='act:form-apply' style='margin-top:10px'>检查并确认修改</a></div></body></html>",traffic_op==0?"填写十进制字节数，0 表示清零本月累计；校正会改变原厂统计记录。":traffic_op==1?"容量为十进制字节数；提醒比例 0–100。保留已读取的类型 2，不改变其计算方式。":"每月清零日为 1–31。关闭规则时仍保留所选日期。");}
static int traffic_recheck(const char*payload,const tf_json*d){char kind[64];if(!json_get(payload,"action",kind,sizeof kind))return 0;(void)d;return strcmp(kind,"traffic.set_limit")!=0;}
static int traffic_action(const char*a){if(!strcmp(a,"traffic")){settings_child_parent=advanced_page==12?12:0;advanced_page=10;scroll_y=0;return 1;}if(!strncmp(a,"traffic-edit:",13)){if(advanced_page!=10||strlen(a+13)!=1||a[13]<'0'||a[13]>'2')return 1;tf_json d;if(!fresh_state(&d))return 1;int op=a[13]-'0',t=tf_key(&d,0,"traffic"),l=tf_key(&d,t,"limit"),c=tf_key(&d,t,"clear_day"),ok=0;long long first=0,second=0,type;int enabled=0;if(op==1){tf_free(&d);show_notice("套餐类型意义尚未核实，限额配置只读");return 1;}if(op==0){long long rx,tx;ok=tf_int(&d,tf_key(&d,t,"month_rx_bytes"),&rx)&&rx>=0&&rx<=109951162777600LL&&tf_int(&d,tf_key(&d,t,"month_tx_bytes"),&tx)&&tx>=0&&tx<=109951162777600LL&&rx<=109951162777600LL-tx;first=ok?rx+tx:0;}else if(op==1){enabled=tf_bool(&d,tf_key(&d,l,"enable"));ok=enabled>=0&&tf_int(&d,tf_key(&d,l,"type"),&type)&&type==2&&tf_int(&d,tf_key(&d,l,"value"),&first)&&first>0&&tf_int(&d,tf_key(&d,l,"ratio"),&second)&&second>=0&&second<=100;}else{enabled=tf_bool(&d,tf_key(&d,c,"enable"));ok=enabled>=0&&tf_int(&d,tf_key(&d,c,"clearday"),&first)&&first>=1&&first<=31;}tf_free(&d);if(!ok){show_notice("当前流量设置不完整或类型尚未核实");return 1;}form_reset();form_kind=4;traffic_op=op;traffic_draft_enabled=enabled;snprintf(form_values[0],513,"%lld",first);snprintf(form_values[1],513,"%lld",second);advanced_page=6;scroll_y=0;return 1;}
 if(!strcmp(a,"traffic-toggle")){if(advanced_page==6&&form_kind==4&&traffic_op==2)traffic_draft_enabled=!traffic_draft_enabled;return 1;}
 if(!strcmp(a,"form-apply")&&advanced_page==6&&form_kind==4){if(!control_guard()||traffic_op==1)return 1;long long value,ratio=0;int ok=traffic_integer(form_values[0],traffic_op==0?0:1,traffic_op==2?31:109951162777600LL,&value)&&(traffic_op!=1||traffic_integer(form_values[1],0,100,&ratio));if(!ok){show_notice("请输入范围内的十进制整数");return 1;}if(traffic_op==0)snprintf(pending,sizeof pending,"{\"action\":\"traffic.calibrate\",\"params\":{\"value\":\"%lld\"}}",value);else if(traffic_op==1)snprintf(pending,sizeof pending,"{\"action\":\"traffic.set_limit\",\"params\":{\"enabled\":%d,\"value\":\"%lld\",\"type\":2,\"ratio\":%lld}}",traffic_draft_enabled,value,ratio);else snprintf(pending,sizeof pending,"{\"action\":\"traffic.set_clear_day\",\"params\":{\"day\":%lld,\"enabled\":%d}}",value,traffic_draft_enabled);snprintf(pending_label,sizeof pending_label,traffic_op==0?"将主卡本月累计校正为 %lld 字节。这会改变当前统计记录。":traffic_op==1?"将主卡现有类型 2 容量规则设为 %lld 字节；开关和提醒比例使用本地草稿所选值。":"将每月清零日设为 %lld；开关使用本地草稿所选值。",value);scroll_y=0;return 1;}return 0;}
#endif
